/**
 * components/dashboard/TagsTab.tsx
 * ---------------------------------------------------------------------------
 * Two cards:
 *   1. "Claim your physical QR tag" form (tag reference + activation code).
 *      Customers can NOT create tags here; they can only claim tags that were
 *      generated by the business and marked as sold.
 *   2. The list of tags this owner has claimed, with a Deactivate button
 *      for active ones.
 */
import type { Dispatch, FormEvent, SetStateAction } from "react";
import type { QRTag } from "../../types";
import type { ClaimForm } from "./dashboardConfig";
import { Card } from "../ui/Card";
import { Field } from "../ui/Field";
import { Empty } from "../ui/Empty";

type TagsTabProps = {
  tags: QRTag[];
  claimForm: ClaimForm;
  setClaimForm: Dispatch<SetStateAction<ClaimForm>>;
  busy: boolean;
  onClaim: (e: FormEvent) => void;
  onDeactivate: (id: string) => void;
};

export function TagsTab({
  tags,
  claimForm,
  setClaimForm,
  busy,
  onClaim,
  onDeactivate,
}: TagsTabProps) {
  return (
    <>
      {/* ---------- Claim a tag ---------- */}
      <Card
        title="Claim your physical QR tag"
        subtitle="You must have a SafeLink tag purchased from an authorised seller. Tags cannot be created from this dashboard."
      >
        <form onSubmit={onClaim} className="form-grid">
          <Field label="Tag reference">
            <input
              required
              maxLength={40}
              autoComplete="off"
              value={claimForm.tag_ref}
              onChange={(e) =>
                // References are always upper case, e.g. SL-000001
                setClaimForm({
                  ...claimForm,
                  tag_ref: e.target.value.toUpperCase(),
                })
              }
              placeholder="e.g. SL-000001"
            />
          </Field>

          <Field label="Concealed activation code">
            <input
              required
              maxLength={100}
              autoComplete="off"
              value={claimForm.activation_code}
              onChange={(e) =>
                setClaimForm({ ...claimForm, activation_code: e.target.value })
              }
              placeholder="Enter the code supplied with your tag"
            />
          </Field>

          <Field label="Tag label (optional)">
            <input
              maxLength={80}
              value={claimForm.label}
              onChange={(e) =>
                setClaimForm({ ...claimForm, label: e.target.value })
              }
              placeholder="My watch tag"
            />
          </Field>

          <p className="fine-print">
            Keep the activation code private. A tag can only be claimed if it
            has been marked as sold and has not already been claimed by
            another account.
          </p>

          <div className="form-actions">
            <button className="button primary" disabled={busy}>
              {busy ? "Claiming tag…" : "Claim SafeLink tag"}
            </button>
          </div>
        </form>
      </Card>

      {/* ---------- Registered tags ---------- */}
      <Card title={`Your registered tags (${tags.length})`}>
        {tags.length ? (
          <div className="record-list">
            {tags.map((tag) => (
              <div className="record" key={tag.qr_id}>
                <div className="record-icon">▦</div>

                <div className="record-main">
                  <strong>{tag.label}</strong>
                  <span>{tag.active ? "Active" : "Deactivated"}</span>
                  <small>Tag ID: {tag.qr_id}</small>
                </div>

                {/* Only active tags can be deactivated */}
                {tag.active && (
                  <button
                    className="button danger small"
                    onClick={() => onDeactivate(tag.qr_id)}
                  >
                    Deactivate
                  </button>
                )}
              </div>
            ))}
          </div>
        ) : (
          <Empty text="No tags claimed yet. Enter your tag reference and activation code above." />
        )}
      </Card>
    </>
  );
}
